    "ce": "# One box around two clips — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 OneBoxAroundTwoClips.py OneBoxAroundTwoClips\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 540 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass OneBoxAroundTwoClips(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # first: x + y = 10\n        first = MathTex(r\"x + y = 10\", font_size=96)\n        first_g = _glyphs(first, [\n            (-2.3284, -0.0172, 0.5591, 0.5201), (-1.2897, 0.023, 0.7646, 0.7635), (-0.2908, -0.1282, 0.5461, 0.7436), (0.7402, 0.0224, 0.7646, 0.2687),\n            (1.7985, 0.1177, 0.3949, 0.7646), (2.3662, 0.1051, 0.4834, 0.7899),\n        ])\n        first.move_to([0, 1, 0])\n\n        # second: x - y = 2\n        second = MathTex(r\"x - y = 2\", font_size=96)\n        second_g = _glyphs(second, [\n            (-2.035, -0.0172, 0.5591, 0.5201), (-0.9963, 0.0224, 0.7003, 0.0459), (0.0026, -0.1282, 0.5461, 0.7436), (1.0335, 0.0224, 0.7646, 0.2687),\n            (2.0855, 0.1177, 0.4581, 0.7646),\n        ])\n        second.move_to([-0.25, -0.7, 0])\n        second.set_z_index(1)\n\n        # box: box, built on first and second where its clip starts\n\n        # 0 s – 1.2 s: first write\n        self.play(Write(VGroup(*first_g[:])), run_time=1.2)\n        # 1.2 s – 2.2 s: second write\n        self.play(Write(VGroup(*second_g[:])), run_time=1)\n        # 2.2 s – 3.2 s\n        self.wait(1)\n        box = SurroundingRectangle(VGroup(first, second), buff=0.2, color=\"#FFFF00\", corner_radius=0.15)\n        box.set_z_index(2)\n        # 3.2 s – 4.1 s: box create\n        self.play(Create(box), run_time=0.9)\n        # 4.1 s – 8.2 s\n        self.wait(4.100001)\n        # 8.2 s – 9 s: box fade_out, first fade_out, second fade_out\n        self.play(FadeOut(box), FadeOut(first), FadeOut(second), run_time=0.8)\n",
    "gl": "# One box around two clips — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl OneBoxAroundTwoClips.py OneBoxAroundTwoClips -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 540 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass OneBoxAroundTwoClips(Scene):\n    default_camera_config = dict(background_color=\"#000000\")\n\n    def construct(self):\n\n        # first: x + y = 10\n        first = Tex(r\"x + y = 10\", font_size=98.9888)\n        first_g = _glyphs(first, [\n            (-2.3284, -0.0172, 0.5591, 0.5201), (-1.2897, 0.023, 0.7646, 0.7635), (-0.2908, -0.1282, 0.5461, 0.7436), (0.7402, 0.0224, 0.7646, 0.2687),\n            (1.7985, 0.1177, 0.3949, 0.7646), (2.3662, 0.1051, 0.4834, 0.7899),\n        ])\n        first.move_to([0, 1, 0])\n\n        # second: x - y = 2\n        second = Tex(r\"x - y = 2\", font_size=98.9888)\n        second_g = _glyphs(second, [\n            (-2.035, -0.0172, 0.5591, 0.5201), (-0.9963, 0.0224, 0.7003, 0.0459), (0.0026, -0.1282, 0.5461, 0.7436), (1.0335, 0.0224, 0.7646, 0.2687),\n            (2.0855, 0.1177, 0.4581, 0.7646),\n        ])\n        second.move_to([-0.25, -0.7, 0])\n        second.set_z_index(1)\n\n        # box: box, built on first and second where its clip starts\n\n        # 0 s – 1.2 s: first write\n        self.play(Write(VGroup(*first_g[:]), stroke_color=\"#FFFFFF\"), run_time=1.2)\n        # 1.2 s – 2.2 s: second write\n        self.play(Write(VGroup(*second_g[:]), stroke_color=\"#FFFFFF\"), run_time=1)\n        # 2.2 s – 3.2 s\n        self.wait(1)\n        box = SurroundingRectangle(VGroup(first, second), buff=0.2, color=\"#FFFF00\").round_corners(0.15)\n        box_g = _glyphs(box, [\n            (0, 0, 1.6661, 1),\n        ])\n        box.set_z_index(2)\n        # 3.2 s – 4.1 s: box create\n        self.play(ShowCreation(VGroup(box_g[0])), run_time=0.9)\n        # 4.1 s – 8.2 s\n        self.wait(4.1)\n        # 8.2 s – 9 s: box fade_out, first fade_out, second fade_out\n        self.play(FadeOut(box), FadeOut(first), FadeOut(second), run_time=0.8)\n"
